function decode_rename(inst):
    // Step 1: Advance decay for all valid digests in sR_RegStatus
    for r = 0 to 64:
        if sR_RegStatus[r].valid == 1:
            if sR_RegStatus[r].decay_ctr > 0:
                sR_RegStatus[r].decay_ctr = sR_RegStatus[r].decay_ctr - 1
            else:
                // 256 decoded instructions elapsed; invalidate stale digest
                sR_RegStatus[r].valid = 0
                sR_RegStatus[r].payload = 0
                sR_RegStatus[r].decay_ctr = 0
    // Step 2: Mark destination register pending
    if inst.writes_register:
        dest_reg = inst.dest_logical_reg
        if dest_reg >= 0 and dest_reg <= 64:
            sR_RegStatus[dest_reg].valid = 0
            sR_RegStatus[dest_reg].payload = inst.rob_tag & 0x3FFF
            sR_RegStatus[dest_reg].decay_ctr = 0
